BEGIN;
-- Local-only quarantine authority; there is deliberately no automatic PDF approval.
DO $$ BEGIN
 IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='lyraseo_report_owner') THEN
  CREATE ROLE lyraseo_report_owner NOLOGIN NOINHERIT NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE NOREPLICATION;
 END IF;
 IF EXISTS(SELECT FROM pg_roles WHERE rolname='lyraseo_report_owner' AND (rolcanlogin OR rolinherit OR rolsuper OR rolbypassrls OR rolcreatedb OR rolcreaterole OR rolreplication)) OR
 EXISTS(SELECT FROM pg_auth_members WHERE member=(SELECT oid FROM pg_roles WHERE rolname='lyraseo_report_owner') OR roleid=(SELECT oid FROM pg_roles WHERE rolname='lyraseo_report_owner')) OR
 EXISTS(SELECT FROM pg_database WHERE datdba=(SELECT oid FROM pg_roles WHERE rolname='lyraseo_report_owner'))
 THEN RAISE EXCEPTION 'UNSAFE_REPORT_ROLE'; END IF;
END $$;
CREATE SCHEMA lyraseo_report;
REVOKE ALL ON SCHEMA lyraseo_report FROM PUBLIC;
GRANT USAGE ON SCHEMA lyraseo_report TO lyraseo_report_owner,lyraseo_runtime,lyraseo_artifact_maintenance;
GRANT USAGE ON SCHEMA public,lyraseo_kernel TO lyraseo_report_owner;
GRANT EXECUTE ON FUNCTION lyraseo_kernel.is_test_database() TO lyraseo_report_owner;
CREATE POLICY report_read ON lyraseo_kernel.test_environment FOR SELECT TO lyraseo_report_owner USING(true);
GRANT SELECT ON lyraseo_kernel.test_environment TO lyraseo_report_owner;
CREATE TABLE lyraseo_report.environment (
 workspace_id text NOT NULL, site_id text NOT NULL, database_oid oid NOT NULL,
 postmaster_started_at timestamptz NOT NULL, maintenance_login text NOT NULL CHECK(maintenance_login='lyraseo_artifact_maintenance'),
 policy text NOT NULL CHECK(policy='LEGACY_REPORT_LOCAL_V1'), PRIMARY KEY(workspace_id,site_id)
);
ALTER TABLE lyraseo_report.environment ENABLE ROW LEVEL SECURITY;
ALTER TABLE lyraseo_report.environment FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_read ON lyraseo_report.environment FOR SELECT TO lyraseo_report_owner USING(true);
GRANT SELECT ON lyraseo_report.environment TO lyraseo_report_owner;
CREATE FUNCTION lyraseo_report.enrolled(w text,s text) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT session_user='lyraseo_artifact_maintenance' AND current_setting('server_version_num')::integer BETWEEN 170000 AND 179999 AND lyraseo_kernel.is_test_database() AND EXISTS(
 SELECT FROM lyraseo_report.environment WHERE (workspace_id,site_id)=(w,s) AND maintenance_login=session_user AND
 database_oid=(SELECT oid FROM pg_database WHERE datname=current_database()) AND postmaster_started_at=pg_postmaster_start_time())
$$;
-- No report FK: scope deletion may remove payload rows while opaque receipts survive.
CREATE TABLE lyraseo_report.decision (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id text NOT NULL,site_id text NOT NULL,report_id text NOT NULL,
 format text NOT NULL CHECK(format IN ('pdf','csv')), state text NOT NULL CHECK(state IN ('classification-blocked','withdrawn')),
 snapshot_hash text NOT NULL,snapshot_length bigint NOT NULL,pdf_hash text NOT NULL,pdf_length bigint NOT NULL,csv_hash text NOT NULL,csv_length bigint NOT NULL,
 evidence_format text,identity_hash text NOT NULL, reviewer text NOT NULL, basis text NOT NULL CHECK(length(basis) BETWEEN 16 AND 1000),
 policy text NOT NULL CHECK(policy='LEGACY_REPORT_LOCAL_V1'), method text NOT NULL CHECK(method IN ('UNKNOWN_GRAMMAR','OPERATOR_WITHDRAWAL')),
 erased boolean NOT NULL, decided_at timestamptz NOT NULL DEFAULT clock_timestamp(), receipt_expires_at timestamptz NOT NULL DEFAULT (clock_timestamp()+interval '180 days'), transaction_id bigint NOT NULL DEFAULT txid_current(),
 CHECK(NOT erased OR state='withdrawn')
);
CREATE INDEX ON lyraseo_report.decision(workspace_id,site_id,report_id,format,decided_at);
ALTER TABLE lyraseo_report.decision ENABLE ROW LEVEL SECURITY;
ALTER TABLE lyraseo_report.decision FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_all ON lyraseo_report.decision TO lyraseo_report_owner USING(true) WITH CHECK(true);
GRANT SELECT,INSERT,DELETE ON lyraseo_report.decision TO lyraseo_report_owner;
CREATE FUNCTION lyraseo_report.immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
 IF TG_OP='DELETE' AND current_user='lyraseo_report_owner' AND lyraseo_report.enrolled(OLD.workspace_id,OLD.site_id)
 AND OLD.receipt_expires_at<=clock_timestamp() AND NOT EXISTS(SELECT FROM public."EvidenceReport" WHERE id=OLD.report_id)
 AND NOT EXISTS(SELECT FROM public."Site" WHERE id=OLD.site_id AND "workspaceId"=OLD.workspace_id AND "deletedAt" IS NULL)
 THEN RETURN OLD; END IF;
 RAISE EXCEPTION 'IMMUTABLE_REPORT_RECEIPT'; END $$;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON lyraseo_report.decision FOR EACH ROW EXECUTE FUNCTION lyraseo_report.immutable();
ALTER TABLE public."EvidenceReport" ALTER COLUMN pdf DROP NOT NULL, ALTER COLUMN csv DROP NOT NULL;
CREATE FUNCTION lyraseo_report.facts(r public."EvidenceReport") RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('domain','PG_JSONB_TEXT_UTF8_V1:PG17','snapshotHash',encode(sha256(convert_to(r.snapshot::text,'UTF8')),'hex'),
 'snapshotLength',octet_length(convert_to(r.snapshot::text,'UTF8')),'pdfHash',encode(sha256(r.pdf),'hex'),'pdfLength',octet_length(r.pdf),
 'csvHash',encode(sha256(convert_to(r.csv,'UTF8')),'hex'),'csvLength',octet_length(convert_to(r.csv,'UTF8')),
 'identityHash',encode(sha256(convert_to((to_jsonb(r)-ARRAY['snapshot','pdf','csv','identifierKey'])::text,'UTF8')),'hex'))
$$;
CREATE FUNCTION lyraseo_report.guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE f jsonb; fmt text; BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.pdf IS NULL OR NEW.csv IS NULL THEN RAISE EXCEPTION 'REPORT_NULL_CREATION'; END IF;
  IF NEW."evidenceFormat" IS NULL AND EXISTS(SELECT FROM lyraseo_report.environment e
   WHERE (e.workspace_id,e.site_id)=(NEW."workspaceId",NEW."siteId")) THEN RAISE EXCEPTION 'LEGACY_REPORT_WRITER_FENCED'; END IF;
  RETURN NEW;
 END IF;
 IF (to_jsonb(OLD)-ARRAY['pdf','csv','identifierKey']) IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['pdf','csv','identifierKey']) OR
 (OLD.pdf IS DISTINCT FROM NEW.pdf AND (OLD.pdf IS NULL OR NEW.pdf IS NOT NULL)) OR
 (OLD.csv IS DISTINCT FROM NEW.csv AND (OLD.csv IS NULL OR NEW.csv IS NOT NULL))
 THEN RAISE EXCEPTION 'IMMUTABLE_REPORT'; END IF;
 IF (to_jsonb(NEW)-'identifierKey') IS NOT DISTINCT FROM (to_jsonb(OLD)-'identifierKey') THEN RETURN NEW; END IF;
 IF current_user<>'lyraseo_report_owner' OR NOT lyraseo_report.enrolled(OLD."workspaceId",OLD."siteId") THEN RAISE EXCEPTION 'REPORT_FORBIDDEN'; END IF;
 f:=lyraseo_report.facts(OLD);
 FOREACH fmt IN ARRAY ARRAY['pdf','csv'] LOOP
  IF (fmt='pdf' AND OLD.pdf IS DISTINCT FROM NEW.pdf) OR (fmt='csv' AND OLD.csv IS DISTINCT FROM NEW.csv) THEN
   IF NOT EXISTS(SELECT FROM lyraseo_report.decision d WHERE (d.workspace_id,d.site_id,d.report_id,d.format)=(OLD."workspaceId",OLD."siteId",OLD.id,fmt)
    AND d.state='withdrawn' AND d.erased AND d.transaction_id=txid_current() AND d.snapshot_hash=f->>'snapshotHash'
    AND d.identity_hash=f->>'identityHash' AND d.pdf_hash=f->>'pdfHash' AND d.csv_hash=f->>'csvHash'
    AND d.snapshot_length=(f->>'snapshotLength')::bigint AND d.pdf_length=(f->>'pdfLength')::bigint AND d.csv_length=(f->>'csvLength')::bigint)
   THEN RAISE EXCEPTION 'REPORT_ERASURE_UNATTESTED'; END IF;
  END IF;
 END LOOP;
 RETURN NEW;
END $$;
CREATE TRIGGER report_guard BEFORE INSERT OR UPDATE ON public."EvidenceReport" FOR EACH ROW EXECUTE FUNCTION lyraseo_report.guard();
-- Runtime metadata selectors retain parity; payload access goes through locked operations.
-- BEGIN REPORT PAYLOAD PRIVILEGE GUARD
-- A table revoke does not remove independent column ACLs. Remove both, including
-- PUBLIC. Unexpected effective inherited access fails closed without role changes.
REVOKE SELECT ON "EvidenceReport" FROM PUBLIC;
REVOKE SELECT(snapshot,pdf,csv) ON "EvidenceReport" FROM PUBLIC;
DO $report_acl$ DECLARE principal text; BEGIN
 FOREACH principal IN ARRAY ARRAY['lyraseo_runtime','lyraseo_identity','lyraseo_dispatch','lyraseo_operator','lyraseo_artifact_maintenance','anon','authenticated'] LOOP
  IF EXISTS(SELECT FROM pg_roles WHERE rolname=principal) THEN
   EXECUTE format('REVOKE SELECT ON public."EvidenceReport" FROM %I',principal);
   EXECUTE format('REVOKE SELECT(snapshot,pdf,csv) ON public."EvidenceReport" FROM %I',principal);
  END IF;
 END LOOP;
 FOREACH principal IN ARRAY ARRAY['lyraseo_runtime','lyraseo_identity','lyraseo_dispatch','lyraseo_operator','lyraseo_artifact_maintenance','anon','authenticated'] LOOP
  IF EXISTS(SELECT FROM pg_roles WHERE rolname=principal) AND
   (has_column_privilege(principal,'public."EvidenceReport"','snapshot','SELECT') OR
    has_column_privilege(principal,'public."EvidenceReport"','pdf','SELECT') OR
    has_column_privilege(principal,'public."EvidenceReport"','csv','SELECT') OR EXISTS(
     SELECT FROM pg_roles reachable WHERE
      (pg_has_role(principal,reachable.rolname::text,'USAGE') OR pg_has_role(principal,reachable.rolname::text,'SET')) AND
      (has_column_privilege(reachable.rolname::text,'public."EvidenceReport"','snapshot','SELECT') OR
       has_column_privilege(reachable.rolname::text,'public."EvidenceReport"','pdf','SELECT') OR
       has_column_privilege(reachable.rolname::text,'public."EvidenceReport"','csv','SELECT'))))
  THEN RAISE EXCEPTION 'UNSAFE_REPORT_PAYLOAD_PRIVILEGE: %',principal; END IF;
 END LOOP;
END $report_acl$;
-- END REPORT PAYLOAD PRIVILEGE GUARD
GRANT SELECT(id,"workspaceId","siteId",title,"evidenceFormat","createdAt") ON public."EvidenceReport" TO lyraseo_runtime;
GRANT SELECT ON public."EvidenceReport",public."Workspace",public."Site",public."Membership",public."SiteGrant",public."ProductUser" TO lyraseo_report_owner;
GRANT UPDATE(id) ON public."Workspace",public."Site" TO lyraseo_report_owner;
GRANT UPDATE(pdf,csv) ON public."EvidenceReport" TO lyraseo_report_owner;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['EvidenceReport','Workspace','Site','Membership','SiteGrant','ProductUser'] LOOP
 EXECUTE format('CREATE POLICY report_owner_read ON public.%I FOR SELECT TO lyraseo_report_owner USING(true)',t);
 END LOOP;
END $$;
CREATE POLICY report_owner_lock ON public."Workspace" FOR UPDATE TO lyraseo_report_owner USING(true) WITH CHECK(false);
CREATE POLICY report_owner_lock ON public."Site" FOR UPDATE TO lyraseo_report_owner USING(true) WITH CHECK(false);
CREATE POLICY report_owner_write ON public."EvidenceReport" FOR UPDATE TO lyraseo_report_owner USING(true) WITH CHECK(true);
CREATE FUNCTION lyraseo_report.permission(w text,s text) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT session_user='lyraseo_runtime' AND current_setting('app.workspace_id',true)=w AND EXISTS(
 SELECT FROM public."Workspace" ws JOIN public."Site" st ON st."workspaceId"=ws.id
 JOIN public."Membership" m ON m."workspaceId"=ws.id JOIN public."ProductUser" u ON u.id=m."userId"
 WHERE ws.id=w AND st.id=s AND ws."deletedAt" IS NULL AND st."deletedAt" IS NULL AND NOT u.suspended AND
 u.id=current_setting('app.actor_id',true) AND (m.role IN ('OWNER','ADMIN') OR EXISTS(SELECT FROM public."SiteGrant" g
 WHERE (g."workspaceId",g."siteId",g."userId")=(w,s,u.id))))
$$;
CREATE FUNCTION lyraseo_report.export(w text,s text,rid text,fmt text) RETURNS TABLE(id text,pdf bytea,csv text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE r public."EvidenceReport"; BEGIN
 IF fmt NOT IN ('pdf','csv') OR NOT lyraseo_report.permission(w,s) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
 PERFORM 1 FROM public."Workspace" WHERE public."Workspace".id=w FOR SHARE;
 PERFORM 1 FROM public."Site" WHERE ("workspaceId",public."Site".id)=(w,s) FOR SHARE;
 SELECT * INTO r FROM public."EvidenceReport" er WHERE (er."workspaceId",er."siteId",er.id)=(w,s,rid) FOR SHARE;
 IF r.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
 IF r."evidenceFormat" IS DISTINCT FROM 'saved-evidence-v2' THEN
  IF EXISTS(SELECT FROM lyraseo_report.decision WHERE (workspace_id,site_id,report_id)=(w,s,rid) AND state='withdrawn') THEN RAISE EXCEPTION 'REPORT_WITHDRAWN'; END IF;
  RAISE EXCEPTION 'LEGACY_REVIEW';
 END IF;
 IF NOT lyraseo_report.permission(w,s) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
 RETURN QUERY SELECT r.id,CASE WHEN fmt='pdf' THEN r.pdf END,CASE WHEN fmt='csv' THEN r.csv END;
END $$;
CREATE FUNCTION lyraseo_report.inspect(w text,s text,rid text,payload boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE r public."EvidenceReport"; BEGIN
 IF NOT lyraseo_report.enrolled(w,s) THEN RAISE EXCEPTION 'REPORT_UNENROLLED'; END IF;
 PERFORM 1 FROM public."Workspace" WHERE id=w FOR SHARE;
 PERFORM 1 FROM public."Site" WHERE ("workspaceId",id)=(w,s) FOR SHARE;
 SELECT * INTO r FROM public."EvidenceReport" WHERE ("workspaceId","siteId",id)=(w,s,rid) FOR SHARE;
 IF r.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
 IF octet_length(r.snapshot::text)>1000000 OR octet_length(r.pdf)>10485760 OR octet_length(r.csv)>10485760 THEN RAISE EXCEPTION 'REPORT_INSPECTION_LIMIT'; END IF;
 RETURN lyraseo_report.facts(r)||jsonb_build_object('reportId',r.id,'evidenceFormat',r."evidenceFormat",'classification','classification-blocked','reason','UNKNOWN_HISTORICAL_GRAMMAR')||
 CASE WHEN payload THEN jsonb_build_object('snapshot',r.snapshot,'pdfBase64',encode(r.pdf,'base64'),'csv',r.csv) ELSE '{}'::jsonb END;
END $$;
CREATE FUNCTION lyraseo_report.withdraw(w text,s text,rid text,expected jsonb,basis_ text,erase_ boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE r public."EvidenceReport"; f jsonb; fmt text; BEGIN
 IF NOT lyraseo_report.enrolled(w,s) THEN RAISE EXCEPTION 'REPORT_UNENROLLED'; END IF;
 IF length(basis_) NOT BETWEEN 16 AND 1000 THEN RAISE EXCEPTION 'REPORT_BASIS_REQUIRED'; END IF;
 PERFORM 1 FROM public."Workspace" WHERE id=w FOR SHARE;
 PERFORM 1 FROM public."Site" WHERE ("workspaceId",id)=(w,s) FOR UPDATE;
 SELECT * INTO r FROM public."EvidenceReport" WHERE ("workspaceId","siteId",id)=(w,s,rid) FOR UPDATE;
 IF r.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
 IF r."evidenceFormat" IS NOT NULL THEN RAISE EXCEPTION 'REPORT_NOT_LEGACY'; END IF;
 -- No stored historical contract proves binary content separable from frozen facts.
 -- Keep it quarantined until a separately reviewed format-specific classifier exists.
 IF erase_ THEN RAISE EXCEPTION 'REPORT_CLASSIFICATION_BLOCKED'; END IF;
 IF r.pdf IS NULL OR r.csv IS NULL THEN
  IF EXISTS(SELECT FROM lyraseo_report.decision WHERE (workspace_id,site_id,report_id)=(w,s,rid) AND state='withdrawn') THEN RETURN jsonb_build_object('state','withdrawn','idempotent',true); END IF;
  RAISE EXCEPTION 'UNATTESTED_MISSING_PAYLOAD';
 END IF;
 f:=lyraseo_report.facts(r);
 IF f IS DISTINCT FROM expected THEN RAISE EXCEPTION 'REPORT_CHANGED'; END IF;
 IF (SELECT count(DISTINCT format) FROM lyraseo_report.decision d WHERE (d.workspace_id,d.site_id,d.report_id)=(w,s,rid)
 AND d.state='withdrawn' AND d.snapshot_hash=f->>'snapshotHash' AND d.pdf_hash=f->>'pdfHash' AND d.csv_hash=f->>'csvHash')=2
 THEN RETURN f||jsonb_build_object('state','withdrawn','idempotent',true); END IF;
 FOREACH fmt IN ARRAY ARRAY['pdf','csv'] LOOP
 INSERT INTO lyraseo_report.decision(workspace_id,site_id,report_id,format,state,snapshot_hash,snapshot_length,pdf_hash,pdf_length,csv_hash,csv_length,evidence_format,identity_hash,reviewer,basis,policy,method,erased)
 VALUES(w,s,rid,fmt,'withdrawn',f->>'snapshotHash',(f->>'snapshotLength')::bigint,f->>'pdfHash',(f->>'pdfLength')::bigint,f->>'csvHash',(f->>'csvLength')::bigint,r."evidenceFormat",f->>'identityHash',session_user,basis_,'LEGACY_REPORT_LOCAL_V1','OPERATOR_WITHDRAWAL',erase_);
 END LOOP;
 IF erase_ THEN UPDATE public."EvidenceReport" SET pdf=NULL,csv=NULL WHERE id=rid; END IF;
 RETURN f||jsonb_build_object('state','withdrawn','erased',erase_,'derivative','unavailable','reason','EXACT_RETAINED_FACT_CONTRACT_REQUIRED');
END $$;
-- Fixed bounded projection generated from legacy-evidence.ts; it is read filtering,
-- never an exact reconstruction or a destructive transform.
CREATE FUNCTION lyraseo_report.snapshot(w text,s text,rid text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET jit=off AS $$
DECLARE value jsonb; BEGIN
 IF NOT lyraseo_report.permission(w,s) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
 PERFORM 1 FROM public."Workspace" WHERE id=w FOR SHARE;
 PERFORM 1 FROM public."Site" WHERE ("workspaceId",id)=(w,s) FOR SHARE;
 PERFORM 1 FROM public."EvidenceReport" WHERE ("workspaceId","siteId",id)=(w,s,rid) FOR SHARE;
 IF EXISTS(SELECT FROM public."EvidenceReport" WHERE ("workspaceId","siteId",id)=(w,s,rid) AND "evidenceFormat"='saved-evidence-v2') THEN
  SELECT snapshot INTO value FROM public."EvidenceReport" WHERE ("workspaceId","siteId",id)=(w,s,rid);
 ELSE
 SELECT (WITH bounded AS MATERIALIZED (SELECT CASE WHEN jsonb_typeof(snapshot)='object' THEN (SELECT coalesce(jsonb_object_agg(k,v),'{}'::jsonb) FROM (VALUES ('scope',CASE WHEN jsonb_typeof((snapshot->'scope'))='object' THEN (SELECT coalesce(jsonb_object_agg(k,v),'{}'::jsonb) FROM (VALUES ('workspaceId',CASE WHEN jsonb_typeof(((snapshot->'scope')->'workspaceId'))='string' AND length(((snapshot->'scope')->'workspaceId') #>> '{}')<=128 AND octet_length(((snapshot->'scope')->'workspaceId') #>> '{}')<=512 THEN ((snapshot->'scope')->'workspaceId') END),('siteId',CASE WHEN jsonb_typeof(((snapshot->'scope')->'siteId'))='string' AND length(((snapshot->'scope')->'siteId') #>> '{}')<=128 AND octet_length(((snapshot->'scope')->'siteId') #>> '{}')<=512 THEN ((snapshot->'scope')->'siteId') END)) fields(k,v) WHERE v IS NOT NULL) END),('capturedAt',CASE WHEN jsonb_typeof((snapshot->'capturedAt'))='string' AND length((snapshot->'capturedAt') #>> '{}')<=40 AND octet_length((snapshot->'capturedAt') #>> '{}')<=160 THEN (snapshot->'capturedAt') END),('methodology',CASE WHEN jsonb_typeof((snapshot->'methodology'))='string' AND length((snapshot->'methodology') #>> '{}')<=512 AND octet_length((snapshot->'methodology') #>> '{}')<=2048 THEN (snapshot->'methodology') END),('context',CASE WHEN jsonb_typeof((snapshot->'context'))='object' THEN (SELECT coalesce(jsonb_object_agg(k,v),'{}'::jsonb) FROM (VALUES ('id',CASE WHEN jsonb_typeof(((snapshot->'context')->'id'))='string' AND length(((snapshot->'context')->'id') #>> '{}')<=128 AND octet_length(((snapshot->'context')->'id') #>> '{}')<=512 THEN ((snapshot->'context')->'id') END),('revision',CASE WHEN ((snapshot->'context')->'revision')='null'::jsonb OR (jsonb_typeof(((snapshot->'context')->'revision'))='number' AND octet_length((((snapshot->'context')->'revision'))::text)<=32) THEN ((snapshot->'context')->'revision') END)) fields(k,v) WHERE v IS NOT NULL) END),('comparison',CASE WHEN jsonb_typeof((snapshot->'comparison'))='object' THEN (SELEC