)<=10 AND octet_length(((item1.value->'data')->'startDate') #>> '{}')<=40 THEN ((item1.value->'data')->'startDate') END),('endDate',CASE WHEN jsonb_typeof(((item1.value->'data')->'endDate'))='string' AND length(((item1.value->'data')->'endDate') #>> '{}')<=10 AND octet_length(((item1.value->'data')->'endDate') #>> '{}')<=40 THEN ((item1.value->'data')->'endDate') END),('metrics',CASE WHEN jsonb_typeof(((item1.value->'data')->'metrics'))='object' THEN (SELECT coalesce(jsonb_object_agg(k,v),'{}'::jsonb) FROM (VALUES ('clicks',CASE WHEN (((item1.value->'data')->'metrics')->'clicks')='null'::jsonb OR (jsonb_typeof((((item1.value->'data')->'metrics')->'clicks'))='number' AND octet_length(((((item1.value->'data')->'metrics')->'clicks'))::text)<=32) THEN (((item1.value->'data')->'metrics')->'clicks') END),('impressions',CASE WHEN (((item1.value->'data')->'metrics')->'impressions')='null'::jsonb OR (jsonb_typeof((((item1.value->'data')->'metrics')->'impressions'))='number' AND octet_length(((((item1.value->'data')->'metrics')->'impressions'))::text)<=32) THEN (((item1.value->'data')->'metrics')->'impressions') END)) fields(k,v) WHERE v IS NOT NULL) END),('reportCoverage',CASE WHEN jsonb_typeof(((item1.value->'data')->'reportCoverage'))='object' THEN (SELECT coalesce(jsonb_object_agg(k,v),'{}'::jsonb) FROM (VALUES ('importedRows',CASE WHEN (((item1.value->'data')->'reportCoverage')->'importedRows')='null'::jsonb OR (jsonb_typeof((((item1.value->'data')->'reportCoverage')->'importedRows'))='number' AND octet_length(((((item1.value->'data')->'reportCoverage')->'importedRows'))::text)<=32) THEN (((item1.value->'data')->'reportCoverage')->'importedRows') END)) fields(k,v) WHERE v IS NOT NULL) END)) fields(k,v) WHERE v IS NOT NULL) END)) fields(k,v) WHERE v IS NOT NULL) END ORDER BY item1.ord) FROM jsonb_array_elements(jsonb_path_query_array((snapshot->'sources'),'$[0 to 9]')) WITH ORDINALITY AS item1(value,ord)),'[]'::jsonb) END)) fields(k,v) WHERE v IS NOT NULL) END ELSE doc EN