CREATE FUNCTION lyraseo_report.status(w text,s text,rid text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET jit=off
SET enable_indexscan=on SET enable_bitmapscan=off SET enable_seqscan=off SET enable_sort=off SET plan_cache_mode=force_custom_plan AS $$
DECLARE r public."EvidenceReport"; states jsonb; key_ text:=encode(sha256(convert_to(rid,'UTF8')),'hex'); BEGIN
 IF NOT lyraseo_report.permission(w,s) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
 PERFORM 1 FROM public."Workspace" WHERE id=w FOR SHARE;
 PERFORM 1 FROM public."Site" WHERE ("workspaceId",id)=(w,s) FOR SHARE;
 -- The stored key is fixed-width C-collated hex; [key,key||g) contains
 -- exactly that digest. Keep range order/LIMIT before exact identity matching,
 -- so stale scope statistics cannot turn this point read into a scope scan.
 WITH candidates AS MATERIALIZED (
  SELECT * FROM public."EvidenceReport" WHERE ("workspaceId","siteId")=(w,s)
  AND "identifierKey">=key_ AND "identifierKey"<key_||'g'
  ORDER BY "identifierKey" LIMIT 2 FOR SHARE
 ) SELECT * INTO r FROM candidates WHERE id=rid;
 IF r.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
 IF r."evidenceFormat"='saved-evidence-v2' THEN RETURN '{"pdf":"available","csv":"available"}'::jsonb; END IF;
 SELECT jsonb_object_agg(fmt,coalesce((SELECT d.state FROM lyraseo_report.decision d WHERE
 (d.workspace_id,d.site_id,d.report_id,d.format)=(w,s,rid,fmt) ORDER BY d.decided_at DESC,d.id DESC LIMIT 1),'pending-review')) INTO states FROM unnest(ARRAY['pdf','csv']) fmt;
 RETURN states;
END $$;
CREATE FUNCTION lyraseo_report.page_ids(w text,s text,url_ text) RETURNS SETOF text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 IF NOT lyraseo_report.permission(w,s) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
 RETURN QUERY SELECT id FROM public."EvidenceReport" WHERE ("workspaceId","siteId")=(w,s) AND snapshot->'sources' @>
 jsonb_build_array(jsonb_build_object('kind','raw-http-audit','data',jsonb_build_object('pages',jsonb_build_array(jsonb_build_object('url',url_))))) ORDER BY "createdAt" DESC LIMIT 20;
END $$;
CREATE FUNCTION lyraseo_report.id_key(value text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT encode(sha256(convert_to(value,'UTF8')),'hex')
$$;
-- Persistent keys remove read-time scope hashing. The pure key helper has no
-- database reads or authority; runtime needs it for generated-key INSERTs.
ALTER TABLE public."EvidenceReport" ADD COLUMN "identifierKey" text COLLATE "C" GENERATED ALWAYS AS (lyraseo_report.id_key(id)) STORED NOT NULL CHECK ("identifierKey" ~ '^[a-f0-9]{64}$');
CREATE INDEX "EvidenceReport_opaque_key_idx" ON public."EvidenceReport"("workspaceId","siteId","identifierKey");
CREATE FUNCTION lyraseo_report.resolve_id(w text,s text,key_ text) RETURNS text LANGUAGE plpgsql
SET search_path=pg_catalog SET jit=off SET work_mem='64kB' SET temp_file_limit='16MB' SET lock_timeout='1s'
SET enable_indexscan=on SET enable_bitmapscan=off SET enable_seqscan=off SET enable_sort=off SET plan_cache_mode=force_custom_plan AS $$
DECLARE matches bigint; found_id text; identifier_length bigint; upper_key text; digit integer; BEGIN
 IF NOT lyraseo_report.enrolled(w,s) THEN RAISE EXCEPTION 'REPORT_UNENROLLED'; END IF;
 IF key_ IS NULL OR key_ !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'REPORT_IDENTIFIER_INVALID'; END IF;
 -- Fixed-width hexadecimal keys make [key,next-key) an exact equality bucket,
 -- while retaining a range order the planner cannot discard as a constant.
 FOR digit IN REVERSE 64..1 LOOP
  IF substr(key_,digit,1)<>'f' THEN
   upper_key:=left(key_,digit-1)||substr('0123456789abcdef',strpos('0123456789abcdef',substr(key_,digit,1))+1,1)||repeat('0',64-digit); EXIT;
  END IF;
 END LOOP;
 IF NOT EXISTS(SELECT FROM pg_index WHERE indexrelid=to_regclass('public."EvidenceReport_opaque_key_idx"')
  AND indrelid='public."EvidenceReport"'::regclass AND indisvalid AND indisready)
 THEN RAISE EXCEPTION 'REPORT_IDENTIFIER_INDEX_UNAVAILABLE'; END IF;
 -- Preserve index order with a range lower bound. A materialized LIMIT prevents
 -- equality pushdown from discarding the order and choosing a stale-statistics
 -- workspace scan. At most two candidate identifiers are projected/checked.
 WITH candidates AS MATERIALIZED (
  SELECT CASE WHEN octet_length(id)<=65536 THEN id END bounded_id,octet_length(id) id_length
  FROM public."EvidenceReport" WHERE ("workspaceId","siteId")=(w,s) AND "identifierKey">=key_
  AND (upper_key IS NULL OR "identifierKey"<upper_key)
  ORDER BY "identifierKey" LIMIT 2
 )
 SELECT count(*),min(bounded_id),max(id_length) INTO matches,found_id,identifier_length
 FROM candidates;
 IF matches=0 THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
 IF matches<>1 THEN RAISE EXCEPTION 'REPORT_IDENTIFIER_COLLISION'; END IF;
 IF identifier_length>65536 THEN RAISE EXCEPTION 'REPORT_CLASSIFICATION_BLOCKED_RESOURCE_LIMIT'; END IF;
 RETURN found_id;
EXCEPTION WHEN lock_not_available OR configuration_limit_exceeded OR query_canceled THEN
 RAISE EXCEPTION 'REPORT_IDENTIFIER_RESOURCE_LIMIT';
END $$;
CREATE FUNCTION lyraseo_report.inspect_key(w text,s text,key_ text,payload boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path=pg_catalog SET jit=off SET work_mem='64kB' SET temp_file_limit='16MB' SET lock_timeout='1s' AS $$
DECLARE rid text; value jsonb; BEGIN
 IF NOT lyraseo_report.enrolled(w,s) THEN RAISE EXCEPTION 'REPORT_UNENROLLED'; END IF;
 -- Resolve before taking a site lock, then repeat the bounded lookup after it.
 rid:=lyraseo_report.resolve_id(w,s,key_);
 PERFORM 1 FROM public."Workspace" WHERE id=w FOR SHARE;
 PERFORM 1 FROM public."Site" WHERE ("workspaceId",id)=(w,s) FOR SHARE;
 IF rid IS DISTINCT FROM lyraseo_report.resolve_id(w,s,key_) THEN RAISE EXCEPTION 'REPORT_CHANGED'; END IF;
 IF EXISTS(SELECT FROM public."EvidenceReport" WHERE ("workspaceId","siteId",id)=(w,s,rid) AND octet_length(title)>65536)
 THEN RAISE EXCEPTION 'REPORT_CLASSIFICATION_BLOCKED_RESOURCE_LIMIT'; END IF;
 value:=lyraseo_report.inspect(w,s,rid,payload);
 RETURN (value-'reportId')||jsonb_build_object('idHash',key_,'idByteLength',octet_length(rid));
EXCEPTION WHEN lock_not_available OR configuration_limit_exceeded OR query_canceled THEN
 RAISE EXCEPTION 'REPORT_IDENTIFIER_RESOURCE_LIMIT';
END $$;
CREATE FUNCTION lyraseo_report.withdraw_key(w text,s text,key_ text,expected jsonb,basis_ text,erase_ boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path=pg_catalog SET jit=off SET work_mem='64kB' SET temp_file_limit='16MB' SET lock_timeout='1s' AS $$
DECLARE rid text; BEGIN
 IF NOT lyraseo_report.enrolled(w,s) THEN RAISE EXCEPTION 'REPORT_UNENROLLED'; END IF;
 rid:=lyraseo_report.resolve_id(w,s,key_);
 PERFORM 1 FROM public."Workspace" WHERE id=w FOR SHARE;
 PERFORM 1 FROM public."Site" WHERE ("workspaceId",id)=(w,s) FOR UPDATE;
 IF rid IS DISTINCT FROM lyraseo_report.resolve_id(w,s,key_) THEN RAISE EXCEPTION 'REPORT_CHANGED'; END IF;
 IF NOT EXISTS(SELECT FROM public."EvidenceReport" WHERE ("workspaceId","siteId",id)=(w,s,rid)
  AND octet_length(title)<=65536 AND pg_column_size(snapshot)<=65536 AND octet_length(snapshot::text)<=1000000
  AND octet_length(pdf)<=10485760 AND octet_length(csv)<=10485760)
 THEN RAISE EXCEPTION 'REPORT_CLASSIFICATION_BLOCKED_RESOURCE_LIMIT'; END IF;
 RETURN lyraseo_report.withdraw(w,s,rid,expected,basis_,erase_);
EXCEPTION WHEN lock_not_available OR configuration_limit_exceeded OR query_canceled THEN
 RAISE EXCEPTION 'REPORT_IDENTIFIER_RESOURCE_LIMIT';
END $$;
-- Only this NOLOGIN purpose owner may establish the fixed temporary-file ceiling.
GRANT SET ON PARAMETER temp_file_limit TO lyraseo_report_owner;
CREATE FUNCTION lyraseo_report.membership_step(state bytea,key_ text,budget timestamptz) RETURNS bytea LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
 IF clock_timestamp()>budget THEN RAISE EXCEPTION 'REPORT_INVENTORY_RESOURCE_LIMIT'; END IF;
 RETURN sha256(coalesce(state,sha256(convert_to('REPORT_MEMBERSHIP_V1','UTF8')))||decode(key_,'hex'));
END $$;
CREATE AGGREGATE lyraseo_report.membership_hash(text,timestamptz) (SFUNC=lyraseo_report.membership_step,STYPE=bytea);
CREATE FUNCTION lyraseo_report.inventory(w text,s text,continuation text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET work_mem='64kB' SET temp_file_limit='16MB' AS $$
DECLARE items jsonb; total bigint; version_ text; position_ bigint:=0; expected_total bigint; expected_version text; next_ text; budget_ timestamptz:=clock_timestamp()+interval '5 seconds'; BEGIN
 IF NOT lyraseo_report.enrolled(w,s) THEN RAISE EXCEPTION 'REPORT_UNENROLLED'; END IF;
 IF continuation IS NOT NULL THEN
  IF octet_length(continuation)>128 OR continuation !~ '^offset-v2:[0-9]{1,19}:[0-9]{1,19}:[a-f0-9]{64}$' THEN RAISE EXCEPTION 'REPORT_CURSOR_INVALID'; END IF;
  BEGIN position_:=split_part(continuation,':',2)::bigint; expected_total:=split_part(continuation,':',3)::bigint;
  EXCEPTION WHEN numeric_value_out_of_range THEN RAISE EXCEPTION 'REPORT_CURSOR_INVALID'; END;
  expected_version:=split_part(continuation,':',4);
 END IF;
 PERFORM 1 FROM public."Workspace" WHERE id=w FOR SHARE;
 PERFORM 1 FROM public."Site" WHERE ("workspaceId",id)=(w,s) FOR SHARE;
 IF NOT lyraseo_report.enrolled(w,s) THEN RAISE EXCEPTION 'REPORT_UNENROLLED'; END IF;
 -- One MVCC statement binds membership and page. The materialized scope holds
 -- fixed-size digest keys only; aggregate state is 32 bytes, not string_agg(N).
 -- Sorting/materialization may spill within the 16MB ceiling; CPU work remains
 -- O(all identifier bytes + sort + selected bounded payloads), not constant work.
 -- The 5-second cooperative budget is checked by each aggregate transition;
 -- callers must also establish a statement timeout to cover sort/individual values.
 WITH keys AS MATERIALIZED (
  SELECT lyraseo_report.id_key(id) key_ FROM public."EvidenceReport"
  WHERE ("workspaceId","siteId")=(w,s) AND "evidenceFormat" IS NULL
 ), stats AS (
  SELECT count(*) n,encode(coalesce(lyraseo_report.membership_hash(key_,budget_ ORDER BY key_),sha256(convert_to('REPORT_MEMBERSHIP_V1','UTF8'))),'hex') version FROM keys
 ), collisions AS (SELECT key_ FROM keys GROUP BY key_ HAVING count(*)>1), page_ AS (
  SELECT selected.report,position_+row_number() OVER() ordinal,
   EXISTS(SELECT FROM collisions c WHERE c.key_=lyraseo_report.id_key((selected.report).id)) collision
  FROM (SELECT r AS report FROM public."EvidenceReport" r
   WHERE (r."workspaceId",r."siteId")=(w,s) AND r."evidenceFormat" IS NULL
   ORDER BY r.id OFFSET position_ LIMIT 100) selected
 )
 SELECT stats.n,stats.version,coalesce((SELECT jsonb_agg(jsonb_build_object(
  'id',CASE WHEN octet_length((p.report).id)<=1024 THEN (p.report).id END,
  'idHash',lyraseo_report.id_key((p.report).id),'idByteLength',octet_length((p.report).id),'ordinal',p.ordinal,
  'identifierStatus',CASE WHEN p.collision THEN 'identifier-collision' WHEN octet_length((p.report).id)>1024 THEN 'oversized-identifier' ELSE 'identified' END,
  'evidenceFormat',(p.report)."evidenceFormat",'classification','classification-blocked','reason','UNKNOWN_HISTORICAL_GRAMMAR',
  'withdrawn',EXISTS(SELECT FROM lyraseo_report.decision d WHERE (d.workspace_id,d.site_id,d.report_id)=(w,s,(p.report).id) AND d.state='withdrawn'),
  'facts',CASE WHEN octet_length((p.report).id)<=65536 AND octet_length((p.report).title)<=65536
   AND pg_column_size((p.report).snapshot)<=65536 AND octet_length((p.report).snapshot::text)<=1000000 AND octet_length((p.report).pdf)<=10485760 AND octet_length((p.report).csv)<=10485760
   THEN lyraseo_report.facts(p.report) END,
  'factStatus',CASE WHEN octet_length((p.report).id)<=65536 AND octet_length((p.report).title)<=65536
   AND pg_column_size((p.report).snapshot)<=65536 AND octet_length((p.report).snapshot::text)<=1000000 AND octet_length((p.report).pdf)<=10485760 AND octet_length((p.report).csv)<=10485760
   THEN 'hashed' ELSE 'classification-blocked-resource-limit' END) ORDER BY p.ordinal::bigint) FROM page_ p),'[]'::jsonb)
 INTO total,version_,items FROM stats;
 IF continuation IS NOT NULL AND (expected_total,expected_version) IS DISTINCT FROM (total,version_) THEN RAISE EXCEPTION 'REPORT_INVENTORY_CHANGED'; END IF;
 IF position_>total THEN RAISE EXCEPTION 'REPORT_CURSOR_INVALID'; END IF;
 IF total-position_>jsonb_array_length(items) THEN next_:='offset-v2:'||(position_+jsonb_array_length(items))||':'||total||':'||version_; END IF;
 RETURN jsonb_build_object('policy','LEGACY_REPORT_LOCAL_V1','boundary','LOCAL_TEST_ONLY_ACTIVE_STORE',
 'counts',jsonb_build_object('legacyTotal',total,'classificationBlocked',total,'safeOriginal',0,'derivativeAvailable',0),
 'items',items,'limit',100,'identifierKeyVersion','REPORT_ID_UTF8_SHA256_V1','nextCursor',next_);
EXCEPTION WHEN configuration_limit_exceeded OR query_canceled THEN
 RAISE EXCEPTION 'REPORT_INVENTORY_RESOURCE_LIMIT';
END $$;
CREATE FUNCTION lyraseo_report.prune(w text,s text) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE removed bigint; BEGIN
 IF NOT lyraseo_report.enrolled(w,s) THEN RAISE EXCEPTION 'REPORT_UNENROLLED'; END IF;
 PERFORM 1 FROM public."Workspace" WHERE id=w FOR SHARE;
 PERFORM 1 FROM public."Site" WHERE ("workspaceId",id)=(w,s) FOR UPDATE;
 IF EXISTS(SELECT FROM public."Site" WHERE ("workspaceId",id)=(w,s) AND "deletedAt" IS NULL) THEN RAISE EXCEPTION 'REPORT_SCOPE_ACTIVE'; END IF;
 DELETE FROM lyraseo_report.decision WHERE (workspace_id,site_id)=(w,s) AND receipt_expires_at<=clock_timestamp()
 AND NOT EXISTS(SELECT FROM public."EvidenceReport" WHERE id=report_id);
 GET DIAGNOSTICS removed=ROW_COUNT; RETURN removed;
END $$;
DO $$ DECLARE p record; BEGIN FOR p IN SELECT oid::regprocedure AS signature FROM pg_proc WHERE pronamespace='lyraseo_report'::regnamespace AND prokind<>'a' LOOP
 EXECUTE format('ALTER FUNCTION %s OWNER TO lyraseo_report_owner',p.signature);
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',p.signature);
 END LOOP; END $$;
ALTER AGGREGATE lyraseo_report.membership_hash(text,timestamptz) OWNER TO lyraseo_report_owner;
REVOKE ALL ON FUNCTION lyraseo_report.membership_hash(text,timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION lyraseo_report.id_key(text) TO lyraseo_runtime;
GRANT EXECUTE ON FUNCTION lyraseo_report.export(text,text,text,text),lyraseo_report.snapshot(text,text,text),lyraseo_report.status(text,text,text),lyraseo_report.page_ids(text,text,text) TO lyraseo_runtime;
GRANT EXECUTE ON FUNCTION lyraseo_report.inventory(text,text,text),lyraseo_report.prune(text,text) TO lyraseo_artifact_maintenance;
GRANT EXECUTE ON FUNCTION lyraseo_report.inspect_key(text,text,text,boolean),lyraseo_report.withdraw_key(text,text,text,jsonb,text,boolean),lyraseo_report.inspect(text,text,text,boolean),lyraseo_report.withdraw(text,text,text,jsonb,text,boolean) TO lyraseo_artifact_maintenance;
COMMIT;
